import { useEffect, useMemo, useState } from 'react';

// ---- inlined from reservoir ----
/**
 * Reservoir sampling (Algorithm R) over a fixed stream: one seeded run, recorded as a
 * per-arrival trace plus the reservoir's full contents after every arrival.
 */

const STREAM = 120;
const K = 12;
const SEED = 20260821;

/** mulberry32: a fixed seed keeps every run identical across reloads. */
function seededRandom(seed: number): () => number {
  let state = seed;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

interface ReservoirStep {
  /** 0-based arrival index of the element processed at this step. */
  arrival: number;
  kept: boolean;
  /** Slot written when kept, -1 otherwise. */
  slot: number;
  /** The keep probability this arrival faced: min(1, k / (arrival + 1)). */
  probability: number;
}

const steps: ReservoirStep[] = [];

/** slotsAfter[s][j]: element held by slot j once s arrivals are processed; -1 while empty. */
const slotsAfter: number[][] = [new Array<number>(K).fill(-1)];

{
  const random = seededRandom(SEED);
  const slots = new Array<number>(K).fill(-1);
  for (let i = 0; i < STREAM; ++i) {
    const probability = Math.min(1, K / (i + 1));
    let slot = -1;
    if (i < K) slot = i;
    else if (random() < probability) slot = Math.floor(random() * K);
    if (slot >= 0) slots[slot] = i;
    steps.push({ arrival: i, kept: slot >= 0, slot, probability });
    slotsAfter.push([...slots]);
  }
}

const TICK_MS = 90;
const HOLD_TICKS = 36;
const FLASH = '#e0538a';
const FLASH_STEPS = 9;
const END = STREAM + HOLD_TICKS;

export default function ReservoirSampling({ width }: { width: number }) {
  const w = Math.max(1, width);
  const cell = w / (STREAM + 2);
  const streamTop = 16;
  const streamH = cell * 0.85;
  const arrivalY = streamTop + streamH + 30;
  const arrivalR = Math.max(4, w * 0.011);
  const boxW = Math.min(w / 15.5, 58);
  const boxH = boxW * 0.72;
  const boxGap = boxW * 0.18;
  const resLeft = (w - (K * boxW + (K - 1) * boxGap)) / 2;
  const resTop = arrivalY + arrivalR + 22;
  const height = Math.round(resTop + boxH + 40);

  // The SSR frame is the fully processed stream; the effect rewinds and replays it.
  const [step, setStep] = useState(STREAM);

  useEffect(() => {
    setStep(0);
    const id = window.setInterval(() => setStep((s) => (s >= END ? 0 : s + 1)), TICK_MS);
    return () => window.clearInterval(id);
  }, []);

  const shown = Math.min(step, STREAM);
  const slots = slotsAfter[shown];

  const cellX = (i: number) => (i + 1) * cell;

  /** The stream timeline, one joined path per element class. */
  const strips = useMemo(() => {
    const square = (i: number) =>
      `M${((i + 1) * cell).toFixed(1)},${streamTop.toFixed(1)}h${(cell * 0.8).toFixed(1)}v${streamH.toFixed(1)}h${(-cell * 0.8).toFixed(1)}Z`;
    const inReservoir = new Set(slotsAfter[shown]);
    const classes = { held: [] as string[], evicted: [] as string[], rejected: [] as string[] };
    for (let i = 0; i < shown; ++i) {
      if (inReservoir.has(i)) classes.held.push(square(i));
      else if (steps[i].kept) classes.evicted.push(square(i));
      else classes.rejected.push(square(i));
    }
    return classes;
  }, [shown, cell, streamTop, streamH]);

  /** Per slot, how recently a post-warmup replacement landed there; 0 means no flash. */
  const flash = useMemo(() => {
    const heat = new Array<number>(K).fill(0);
    for (let j = Math.max(K, shown - FLASH_STEPS); j < shown; ++j) {
      if (steps[j].kept) heat[steps[j].slot] = 1 - (shown - 1 - j) / FLASH_STEPS;
    }
    return heat;
  }, [shown]);

  if (width === 0) return null;

  const arrival = shown > 0 && shown < STREAM ? steps[shown - 1] : null;
  const slotX = (j: number) => resLeft + j * (boxW + boxGap);
  const probability = arrival ? arrival.probability : 0;

  return (
    <svg
      viewBox={`0 0 ${w} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Reservoir sampling: a stream of 120 elements flows past a 12-slot reservoir, each arrival kept with probability k over i shown as its fading opacity, replaced slots flashing — yet the final sample is spread evenly across the whole stream"
    >
      <text x={cellX(0)} y={streamTop - 5} fill="var(--muted)" fontSize={10}>
        stream of {STREAM}
      </text>
      <path d={strips.rejected.join('')} fill="var(--muted)" opacity={0.18} />
      <path d={strips.evicted.join('')} fill="var(--muted)" opacity={0.5} />
      <path d={strips.held.join('')} fill="var(--accent)" />
      {arrival && (
        <g>
          {arrival.kept && (
            <line
              x1={cellX(arrival.arrival) + cell * 0.4}
              y1={arrivalY}
              x2={slotX(arrival.slot) + boxW / 2}
              y2={resTop}
              stroke={FLASH}
              strokeWidth={1.4}
              opacity={0.8}
            />
          )}
          <circle
            cx={cellX(arrival.arrival) + cell * 0.4}
            cy={arrivalY}
            r={arrivalR}
            fill="var(--accent)"
            fillOpacity={probability}
            stroke="var(--accent)"
            strokeWidth={1.2}
          />
        </g>
      )}
      {slots.map((element, j) => (
        <g key={j} transform={`translate(${slotX(j)},${resTop})`}>
          <rect
            width={boxW}
            height={boxH}
            rx={3}
            fill={flash[j] > 0 ? FLASH : 'var(--accent)'}
            opacity={element < 0 ? 0 : flash[j] > 0 ? 0.25 + 0.6 * flash[j] : 0.16}
          />
          <rect width={boxW} height={boxH} rx={3} fill="none" stroke="var(--line)" />
          {element >= 0 && (
            <text
              x={boxW / 2}
              y={boxH / 2 + 4}
              textAnchor="middle"
              fill="var(--text)"
              fontSize={Math.min(12, boxW * 0.34)}
            >
              {element}
            </text>
          )}
        </g>
      ))}
      <text x={4} y={height - 6} fill="var(--muted)" fontSize={11}>
        {shown >= STREAM
          ? `done: every element ended with probability ${K}/${STREAM}`
          : shown <= K
            ? `filling the reservoir: the first ${K} are kept outright`
            : `arrival ${shown} · keep probability ${K}/${shown} ≈ ${Math.round(probability * 100)}%`}
      </text>
    </svg>
  );
}
